    Research: [{ animationClass: "rotateInDownLeft", delay: "0", project: "facct_nokia_paper", imageExt: ".webp", title: "When and How AI Should Assist Brainstorming for AI Impact Assessment", description: "In collaboration with Nokia Bell Labs, we investigated how AI can support, rather than replace, developer teams conducting responsible AI impact assessments during product design.", link: "https://doi.org/10.1145/3805689.3812299", placement: "top" }, { animationClass: "rotateInDownLeft", delay: "0.5s", project: "acm_chi_2026_paper_cover", imageExt: ".jpg", title: "Narratives and Perspectives: How AI Summaries Steer Users' Opinions and Engagement on Social Media", description: "Investigated how two AI summary formats on social media threads (narrative summaries and agreement percentages) influence political opinion change and engagement.", link: "https://doi.org/10.1145/3772318.3790945", placement: "top" }, { animationClass: "slideInUp", delay: "0", project: "acm_chi_2026_paper_cover", imageExt: ".jpg", title: "Sensemaking in Multi-Agent LLM Interfaces: How Users Interpret Transparency and Trustworthiness Cues", description: "Investigated how users interpret transparency and trustworthiness cues across multi-agent LLM interface designs, task types, and user trust dispositions.", link: "https://doi.org/10.1145/3772318.3791157", placement: "top" }, { animationClass: "rotateInDownRight", delay: "0.5s", project: "acm_dis_2025_paper_cover", imageExt: ".jpg", title: "The Impact of Human-Likeness and Self-Disclosure on Message Acceptance in Virtual AI Influencers", description: "Investigated how human-likeness and self-disclosure in short-form videos featuring virtual AI influencers affect message acceptance, including the roles of empathy and anthropomorphising tendencies.", link: "https://doi.org/10.1145/3715336.3735756", placement: "top" }, { animationClass: "rotateInUpRight", delay: "0.5s", project: "feeds_of_distrust_paper_cover", title: "Feeds of Distrust: Investigating How AI-Powered News Chatbots Shape User Trust and Perceptions", description: "Do you rely on chatbots or AI to get the news? This study examines how chatbots can influence our trust and political opinions, potentially more than biased traditional news articles, highlighting the risk of AI-driven information warfare.", link: "https://doi.org/10.1145/3722227", placement: "top" }, { animationClass: "rotateInDownLeft", delay: "0.5s", project: "ai_mediator_study_paper_cover", title: "AI-Driven Mediation Strategies for Audience Depolarisation in Online Debates", description: "In this study, we used prompt-tuned language models to mediate social media debates by applying strategies from the Thomas-Kilmann Conflict Mode Instrument (TKI).", link: "https://doi.org/10.1145/3613904.3642322", placement: "top" }, { animationClass: "slideInUp", delay: "0", project: "dtr_study_paper_cover", title: "Down the Rabbit Hole: Detecting Online Extremism, Radicalisation, and Politicised Hate Speech", description: "Our systematic literature review (SLR) of 51 studies provides the first cross-examination of textual, network, and visual approaches to detecting extremist affiliation, hateful content, and radicalisation towards groups and movements.", link: "https://doi.org/10.1145/3583067", placement: "top" }, { animationClass: "rotateInDownRight", delay: "0.5s", project: "prompt_gan_paper_cover", title: "Prompt-GAN–Customisable Hate Speech and Extremist Datasets via Radicalised Neural Language Models", description: "An adversarial prompt-tuning approach for generating realistic hate and non-hate speech to train hate speech classifiers, improving F1 scores by up to 10.1% over the 2023 state-of-the-art models.", link: "https://doi.org/10.1145/3594315.3594366", placement: "top" }], 
    
